using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.ARC.LogVisualizacionArchivos;using GraphApi.Services.ARC.LogVisualizacionArchivos;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.ARC.LogVisualizacionArchivos{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de LogVisualizacionArchivos: creación, actualización y eliminación.")]    public class LogVisualizacionArchivosMutation    {        [Authorize]        [GraphQLName("createLogVisualizacionArchivos")]        [GraphQLDescription("Crea un nuevo LogVisualizacionArchivo usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadLogVisualizacionArchivos> CreateLogVisualizacionArchivosAsync(            [GraphQLDescription("Datos necesarios para crear el LogVisualizacionArchivo.")]            clCreateLogVisualizacionArchivos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de LogVisualizacionArchivo.")]            ILogVisualizacionArchivosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateLogVisualizacionArchivos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateLogVisualizacionArchivos")]        [GraphQLDescription("Actualiza los campos especificados de un LogVisualizacionArchivo existente.")]        public async Task<clReadLogVisualizacionArchivos?> UpdateLogVisualizacionArchivosAsync(            [GraphQLDescription("Datos del LogVisualizacionArchivo a actualizar.")]            clUpdateLogVisualizacionArchivos objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de LogVisualizacionArchivo.")]            ILogVisualizacionArchivosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateLogVisualizacionArchivos(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteLogVisualizacionArchivos")]        [GraphQLDescription("Elimina un LogVisualizacionArchivo por su ID.")]        public async Task<bool> delLogVisualizacionArchivosAsync(            [GraphQLDescription("ID del LogVisualizacionArchivo a eliminar.")]            int nLogVisualizacionArchivosID,            [Service]            [GraphQLDescription("Servicio para operaciones de LogVisualizacionArchivo.")]            ILogVisualizacionArchivosService objService        )        {            return await objService.DeleteLogVisualizacionArchivos(nLogVisualizacionArchivosID);        }    }}